#!/bin/bash
# Routage des modèles Claude Code : installe ~/.claude/{skills/model-router,agents/mr-*,CLAUDE.md,settings.json}.
# Généré par tools/claude-config/model-router/install.mjs --emit-setup-script. Ne bloque jamais le démarrage.
D=$(mktemp -d)
mkdir -p "$D/." && echo '' | base64 -d > "$D/install.mjs"
mkdir -p "$D/." && echo '' | base64 -d > "$D/CLAUDE.snippet.md"
mkdir -p "$D/skills/model-router" && echo '' | base64 -d > "$D/skills/model-router/SKILL.md"
mkdir -p "$D/agents" && echo '' | base64 -d > "$D/agents/mr-architect.md"
mkdir -p "$D/agents" && echo '' | base64 -d > "$D/agents/mr-builder.md"
mkdir -p "$D/agents" && echo '' | base64 -d > "$D/agents/mr-engineer.md"
mkdir -p "$D/agents" && echo '' | base64 -d > "$D/agents/mr-quickfix.md"
mkdir -p "$D/agents" && echo '' | base64 -d > "$D/agents/mr-reviewer.md"
mkdir -p "$D/agents" && echo '' | base64 -d > "$D/agents/mr-scout.md"
node "$D/install.mjs" || echo "model-router: installation échouée (non bloquant)"
rm -rf "$D"
true
